const sheetDialog=document.createElement('dialog');sheetDialog.style.width='960px';sheetDialog.innerHTML='<div class="modal-head"><h2>合并角色视图</h2><button id="closeSheet">✕</button></div><p>横向白底：40%正面半身大头像＋20%全身正面＋20%单个90°侧面＋20%全身背面。保持原图比例，无文字。</p><label>合并图尺寸<select id="sheetOutputSize"><option value="native">原图高清 · 自动计算，不缩小</option><option value="4k">4K · 3840 × 2160</option><option value="2k">2K · 2560 × 1440</option></select></label><div id="sheetAngles" style="display:flex;gap:15px;flex-wrap:wrap"></div><div class="field-row"><label>排列方式<select id="sheetLayout"><option value="row">横向排列</option><option value="grid">2 × 2 排列</option></select></label><label style="display:flex;align-items:center;gap:8px"><input id="sheetLabels" type="checkbox" style="width:auto">显示视角名称</label></div><p id="sheetWarning" class="subtle"></p><div id="sheetPreview" style="overflow:auto;max-height:45vh;background:#111820;border-radius:6px;padding:10px"></div><p id="sheetStatus" role="status" class="subtle"></p><div class="modal-actions"><button id="previewSheet">更新预览</button><button id="saveSheet" class="primary">保存合并图</button></div>';document.body.append(sheetDialog);document.querySelector('#closeSheet').onclick=()=>sheetDialog.close();let sheetContext=null,sheetCanvas=null,sheetSelection=null,sheetWorking=false;
function loadSheetImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('无法读取某个角度的图片，请刷新后重试'));image.src=url;});}
async function previewSheet(){if(!sheetContext||sheetWorking)return;sheetWorking=true;sheetCanvas=null;document.querySelector('#saveSheet').disabled=true;try{const selected=[...document.querySelectorAll('#sheetAngles input:checked')].map(input=>sheetContext.views.find(v=>v.angle===input.value)).filter(Boolean);if(selected.length!==4)throw Error('请先生成完整四个区域');document.querySelector('#sheetStatus').textContent='正在读取原图…';const images=await Promise.all(selected.map(v=>loadSheetImage(v.url)));const cellHeight=Math.min(1024,Math.max(...images.map(i=>i.naturalHeight))),cellWidth=Math.max(...images.map(i=>Math.round(cellHeight*i.naturalWidth/i.naturalHeight)));const grid=false,cols=grid?Math.min(2,images.length):images.length,rows=Math.ceil(images.length/cols),labelHeight=document.querySelector('#sheetLabels').checked?46:0,gap=20,padding=24;const canvas=document.createElement('canvas');const outputSize=SheetOutputSize.choose(images,selected,document.querySelector('#sheetOutputSize').value);canvas.width=outputSize.width;canvas.height=outputSize.height;const ctx=canvas.getContext('2d');ctx.fillStyle=sheetContext.character.nonWhiteBackground?'#c7c9cc':'#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.font='24px "Microsoft YaHei", sans-serif';ctx.textAlign='center';for(let i=0;i<images.length;i++){const image=images[i],r=CharacterSheet.panelRect(selected[i].angle,canvas.width,canvas.height),x=r.x,y=0,scale=Math.min((r.width-24)/image.naturalWidth,(r.height-24)/image.naturalHeight),w=image.naturalWidth*scale,h=image.naturalHeight*scale;ctx.drawImage(image,x+(r.width-w)/2,y+(r.height-h)/2,w,h);if(false){ctx.fillStyle='#273342';ctx.fillText(selected[i].label,x+cellWidth/2,y+cellHeight+31);}}canvas.style.cssText='display:block;width:100%;height:auto';document.querySelector('#sheetPreview').replaceChildren(canvas);sheetCanvas=canvas;sheetSelection=selected;document.querySelector('#sheetStatus').textContent=canvas.width+' × '+canvas.height+' PNG · '+(document.querySelector('#sheetOutputSize').value==='native'?'保留原图像素':'按所选尺寸合并')+' · 未覆盖单张原图';document.querySelector('#saveSheet').disabled=false;}catch(e){document.querySelector('#sheetStatus').textContent=e.message;}finally{sheetWorking=false}}
document.querySelector('#previewSheet').onclick=previewSheet;for(const id of ['sheetLayout','sheetLabels','sheetOutputSize'])document.querySelector('#'+id).onchange=previewSheet;
document.querySelector('#saveSheet').onclick=async()=>{if(!sheetCanvas||sheetWorking)return;sheetWorking=true;const button=document.querySelector('#saveSheet');button.disabled=true;try{document.querySelector('#sheetStatus').textContent='正在保存到本机…';const blob=await new Promise(resolve=>sheetCanvas.toBlob(resolve,'image/png'));if(!blob)throw Error('无法生成合并图');const params=new URLSearchParams({project_id:sheetContext.projectId,character_id:sheetContext.character.id||sheetContext.character.name,layout:CharacterSheet.spec.layout,sources:JSON.stringify(sheetSelection.map(v=>({angle:v.angle,job_id:v.job_id})))});const r=await fetch('/api/contact-sheet?'+params,{method:'POST',headers:{'Content-Type':'image/png'},body:blob});const result=await r.json();if(!r.ok)throw Error(result.error||'保存失败');sheetContext.character.sheetOutputSize=document.querySelector('#sheetOutputSize').value;sheetContext.character.contactSheets??=[];result.panels=CharacterSheet.spec.panels;result.video_policy=CharacterSheet.spec.video_policy;sheetContext.character.contactSheets.push(result);sheetContext.character.reference_images??={};sheetContext.character.reference_images.four_view=result.image_url;sheetContext.character.contactSheetActive=sheetContext.character.contactSheets.length-1;save();if(tab===0)render();document.querySelector('#sheetStatus').textContent='已保存并更新角色合照，未自动下载。';toast('合并图已保存，原图保留');}catch(e){document.querySelector('#sheetStatus').textContent=e.message;}finally{sheetWorking=false;button.disabled=false}};
function openSheet(c){const entry=activeMulti(c),front=selectedFront(c);const head=typeof currentIdentityPortrait==='function'?currentIdentityPortrait(c):(c.identityPortrait||entry?.jobs?.portrait);const views=CharacterSheet.spec.panels.map(p=>{const image=p.angle==='front'?front:p.angle==='portrait'?head:entry?.jobs?.[p.angle];return {...p,url:image?.image_url,job_id:image?.job_id||image?.id,source:image?.reference_job_id||entry?.reference_job_id};});sheetContext={character:c,projectId:data.project_id||data.title,views};document.querySelector('#sheetOutputSize').value=c.sheetOutputSize||'native';const options=document.querySelector('#sheetAngles');options.replaceChildren();for(const view of views){const label=document.createElement('label');label.style.cssText='display:flex;align-items:center;gap:7px';const check=document.createElement('input');check.type='checkbox';check.value=view.angle;check.disabled=true;check.checked=!!view.url;check.style.cssText='width:auto;margin:0';check.onchange=previewSheet;label.append(check,document.createTextNode(view.label+(view.url?'':'（待生成）')));options.append(label)}document.querySelector('#sheetWarning').textContent='使用各角度当前采用的图片合并。高清放大或参考版本不同，不要求重新生成其他角度。';document.querySelector('#sheetLayout').closest('label').style.display='none';document.querySelector('#sheetLabels').closest('label').style.display='none';sheetDialog.showModal();previewSheet();}
const charactersBeforeContactSheet=characters;
characters=function(){charactersBeforeContactSheet();const c=data.characters[ci];if(!c||c.view!=='multi')return;const actions=document.querySelector('#panel .preview-actions');if(!actions)return;const merge=document.createElement('button');merge.id='mergeCharacterViews';merge.textContent='▦ 合成人物设定母图';merge.onclick=()=>openSheet(c);actions.append(merge);actions.style.flexWrap='wrap';if(!c.contactSheets?.length)return;
const card=document.createElement('section');card.id='contactSheetDisplay';card.style.cssText='margin:18px 0 0;padding-top:17px;border-top:1px solid var(--line)';const heading=document.createElement('div');heading.style.cssText='display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px;flex-wrap:wrap';const title=document.createElement('b');title.textContent='人物多视图合照 · 可作 H3 身份参考';heading.append(title);const version=document.createElement('select');version.setAttribute('aria-label','合并图版本');version.style.cssText='width:auto;max-width:230px;margin:0;font-size:11px;padding:6px';for(let i=c.contactSheets.length-1;i>=0;i--){const option=document.createElement('option');option.value=String(i);option.textContent='V'+(i+1)+' · '+new Date(c.contactSheets[i].created_at).toLocaleString('zh-CN');version.append(option)}const current=Number.isInteger(c.contactSheetActive)&&c.contactSheets[c.contactSheetActive]?c.contactSheetActive:c.contactSheets.length-1;version.value=String(current);heading.append(version);card.append(heading);const zoom=document.createElement('a');zoom.target='_blank';zoom.rel='noopener';zoom.title='点击查看原尺寸合并图';const image=document.createElement('img');image.style.cssText='display:block;width:100%;max-height:430px;object-fit:contain;background:#080d14;border-radius:6px';image.alt=c.name+' · 合并多面参考图';zoom.append(image);card.append(zoom);const info=document.createElement('p');info.className='subtle';card.append(info);const controls=document.createElement('div');controls.style.cssText='display:flex;gap:15px;font-size:11px';const open=document.createElement('a');open.textContent='放大查看 ↗';open.target='_blank';open.rel='noopener';open.style.color='var(--green)';const download=document.createElement('a');download.textContent='下载 PNG';download.download=c.name+'-合并参考图.png';download.style.color='var(--green)';controls.append(open,download);card.append(controls);const stale=document.createElement('p');stale.className='subtle';stale.style.color='#e9bd87';card.append(stale);
function displaySheet(index){const sheet=c.contactSheets[index];image.src=sheet.image_url;zoom.href=sheet.image_url;open.href=sheet.image_url;download.href=sheet.image_url+'?download=1';info.textContent=sheet.width+' × '+sheet.height+' · '+(sheet.layout===CharacterSheet.spec.layout?'40/20/20/20 人物设定图':sheet.layout==='grid'?'历史2 × 2 排列':'历史横向排列')+' · 点击图片可放大';try{const sources=typeof sheet.sources==='string'?JSON.parse(sheet.sources):sheet.sources||[];const m=activeMulti(c);const changed=sources.some(source=>{const id=source.angle==='front'?selectedFront(c)?.job_id:m?.jobs?.[source.angle]?.id;return id&&id!==source.job_id});stale.textContent=changed?'部分单张视图已更新，这张合并图保留旧版本；可重新合并。':'';}catch{stale.textContent=''}}
version.onchange=()=>{c.contactSheetActive=Number(version.value);displaySheet(c.contactSheetActive);save()};displaySheet(current);actions.after(card);
};render();
